-- Extend six existing canonical pedagogy/informatics lessons with original
-- scenario-based teaching aids. No Telegram text is reproduced.
-- Release only with user approval; preserve original lesson IDs and progress.
begin;
do $enrich_v2$
declare r record;
begin
 for r in select * from jsonb_to_recordset($items$[{"module":"M16","slug":"informatika-oqitish-yondashuvlari-va-metodikasi","addition":"## Metodik tizimni imtihon savolida aniqlash [PEDGULI-EXPAND-2026-02]\n\n**Maqsad – mazmun – metod – shakl – vosita – baholash** orasida uyg‘unlik bo‘lishi kerak. Informatika darsining samarasi faqat taqdimotda emas, o‘quvchining kuzatiladigan harakatida aks etadi.\n\n| O‘quv natijasi | Dalil | Mos faoliyat |\n|---|---|---|\n| SQL bilan ma’lumotni filtrlash | Kerakli natijani qaytargan so‘rov | Jadval va WHERE shartini amaliy sinash |\n| Sikl ishlashini tushuntirish | Qadamlar va o‘zgaruvchi qiymatlari jadvali | Siklni kichik misolda izma-iz kuzatish |\n| Tarmoq xavfini aniqlash | Vaziyatga asoslangan xavf tahlili | Sozlamani xavf–oqibat bo‘yicha tekshirish |\n| Ikki algoritmni tanlash | Vaqt, aniqlik, chegaraviy kirish mezonlari | Bir xil test ma’lumotlari bilan taqqoslash |\n\n### Attestatsiya mezoni\n\n1. **Maqsad** kuzatiladigan fe’l bilan ifodalanadimi?\n2. **Dars faoliyati** shu maqsadga olib boradimi?\n3. **Baholash** o‘quvchi bajargan ishga tayanadimi?\n4. **Tashkiliy cheklov** bo‘lsa, natijani pasaytirmay shakl moslashtirilganmi?\n\n**Mini-keys:** kompyuter kam bo‘lsa, juftliklar rollarni navbatma-navbat almashtirib, har bir kishi kodni tushuntirishi va bir qismini mustaqil bajarishi lozim. Qurilma cheklovi baholash imkoniyatini bekor qilmaydi.\n\n**Manba izi:** M16 metodik tizim va informatika o‘qitish yondashuvlari darsi; mustaqil tahliliy qo‘shimcha."},{"module":"M16","slug":"talimiy-vaziyat-va-pedagogik-qarorni-baholash","addition":"## Dastur xatosidan pedagogik qarorgacha [PEDGULI-EXPAND-2026-02]\n\nDasturlashda xato bilan ishlash metodikasi **xatoni ustozning o‘zi tuzatishi** emas, o‘quvchiga sababni izlash va dalil bilan tekshirish ko‘nikmasini berishdir.\n\n| Belgilar | Mos tashxis savoli | O‘quvchi uchun tekshiruv |\n|---|---|---|\n| Python IndexError | Indeks ro‘yxat chegarasidami? | Uzunlik va murojaatni taqqoslash |\n| Sikl to‘xtamaydi | Shartdagi o‘zgaruvchi o‘zgaradimi? | Qadamlar jadvalini tuzish |\n| SQL ortiqcha satr qaytardi | Filtr sharti qanday ishlaydi? | Misol satrlarda WHERE ni sinash |\n| Matndagi belgi buzildi | Qaysi kodlash ishlatilgan? | Kirish va chiqish kodlashini moslashtirish |\n| Dastur faqat odatiy holatda ishlaydi | Chegaraviy qiymatlar sinovdan o‘tdimi? | Bo‘sh, minimal va maksimal holatlarni tekshirish |\n\n### Pedagogik qaror bosqichlari\n\n1. Muammoni aniq kuzatish.\n2. O‘quvchining taxminiy tushunchasini aniqlash.\n3. Minimal qayta tiklanuvchi misol berish.\n4. Bir vaqtning o‘zida **bitta** sababni sinash.\n5. Yangi misolda mustaqil qo‘llashni tekshirish.\n\n**Chalg‘ituvchi variant:** “Kodni tezroq tugatish uchun o‘qituvchi to‘g‘ri kodni beradi” — topshiriqni tugatishi mumkin, ammo mustaqil debugging maqsadiga zid.\n\n**Manba izi:** M16 ta’limiy vaziyat, diagnostika va qarorni baholash darsi; mazmun mustaqil yozilgan."},{"module":"M14","slug":"talim-samaradorligini-taminlash","addition":"## Faollik va o‘rganish samaradorligi [PEDGULI-EXPAND-2026-02]\n\nFaol metodning **nomi** emas, o‘quvchi nima qilgani va qanday dalil qoldirgani muhim. Guruhdagi ikki faol ishtirokchi boshqalar nomidan hamma ishni bajarsa, natija hamma uchun baholandi, deyish mumkin emas.\n\n| Muammo | Ta’sirli choralar | Tekshiriladigan dalil |\n|---|---|---|\n| Guruhning ayrim a’zolari chetda qoldi | Yakka kichik topshiriq va navbatli rollar | Har bir o‘quvchining qisqa izohi |\n| Darsda amaliy mashqqa vaqt yetmadi | Vaqt va mashqlar ustuvorligini moslash | Dars oxiridagi mini-diagnostika |\n| Boshlang‘ich tayyorgarlik farq qiladi | Darajalangan ko‘mak | Bir xil maqsadga turlicha yo‘l bilan erishish |\n| O‘qituvchi faqat o‘zi yechim ko‘rsatdi | Bajar–tekshir–tushuntir davrasi | Mustaqil yechim va qayta aloqa |\n\n**Osondan murakkabga emas, natijadan vazifaga:** avval maqsad va baholash ko‘rsatkichini aniqlang. So‘ng unga yetaklaydigan jarayonni tuzing.\n\n**Manba izi:** M14 KS.02 ta’lim samaradorligi darsi, kasb standarti A/02.6; mazmun original."},{"module":"M14","slug":"tarbiyaviy-faoliyatni-tashkil-etish","addition":"## Raqamli madaniyat orqali tarbiyaviy natija [PEDGULI-EXPAND-2026-02]\n\nInformatika darsidagi tarbiyaviy ish faqat umumiy suhbat bilan cheklanmaydi. Raqamli loyihada halollik, mualliflik, o‘zaro hurmat, mas’uliyat va foydalanuvchi huquqlari real ishga tatbiq etilishi mumkin.\n\n- **Mualliflik:** loyiha ichidagi begona rasm yoki koddan foydalanish shartlarini aniqlab, manbani ko‘rsatish.\n- **Hamkorlik:** guruhda navbat va mas’uliyatni ochiq kelishish; mehnat hissasini tan olish.\n- **Muloqot:** bahsli masalada fikrni dalil bilan himoya qilish, shaxsni emas g‘oyani tahlil qilish.\n- **Raqamli xavfsizlik:** boshqa bolalarga oid ma’lumotlarni ruxsatsiz tarqatmaslik.\n\n**Vaziyatni farqlash:** bolalar masxara qilayotganida darhol xavfsiz muhitni tiklash – KS.05, keyin o‘zaro hurmat va javobgarlik haqida davomli tarbiyaviy ish – KS.04. Savolda asosiy urg‘uni tekshiring.\n\n**Manba izi:** M14 KS.04 tarbiyaviy faoliyat darsi va KS.05 xavfsiz muhit darsi; original keyslar."},{"module":"M14","slug":"oz-ozini-rivojlantirish-va-kasbiy-osish","addition":"## Kasbiy refleksiyani dalilga tayash [PEDGULI-EXPAND-2026-02]\n\n**Refleksiya** — “darsim yaxshi o‘tdi” degan umumiy taassurot emas. O‘qituvchi natijani maqsad, o‘quvchi xatosi, ishtiroki va baholash ko‘rsatkichlari asosida tahlil qiladi.\n\n| Bosqich | Amaliy savol |\n|---|---|\n| Kuzatish | Qaysi o‘quv natijasi kutilgan darajada bo‘lmadi? |\n| Sabab taxmini | Qaysi mashq, tushuntirish yoki resurs yetishmadi? |\n| O‘zgarish | Keyingi darsning aynan qaysi qismi yangilanadi? |\n| Qayta tekshirish | Yangi usul samaradorligini nima bilan taqqoslayman? |\n\n**Maxfiylik muhim:** dars videosi yoki o‘quvchi natijalaridan refleksiya uchun foydalanganda shaxsiy ma’lumotni muhofaza qilish va tegishli ruxsatlarga rioya etish kerak.\n\n**Manba izi:** M14 KS.06 o‘z ustida ishlash va kasbiy o‘sish darsi; mustaqil amaliy qo‘llanma."},{"module":"M15","slug":"dars-turlari-rejalashtirish-va-sinfni-boshqarish","addition":"## Diagnostika, dars tuzilishi va boshqaruv [PEDGULI-EXPAND-2026-02]\n\nDars turi va metod bir xil tushuncha emas. **Dars turi** ustuvor didaktik vazifani, **metod** esa o‘quvchi bilan faoliyatni qanday tashkil etishni bildiradi.\n\n| Vaziyat | Ustuvor vazifa | Mos tekshiruv |\n|---|---|---|\n| Yangi tushuncha bayon qilinadi | Tushunchani anglash | Qisqa izoh va misol |\n| Bilimni mustahkamlash | Oldingi bilimni yangi mashqqa qo‘llash | Bir necha mustaqil vazifa |\n| Nazorat mashg‘uloti | O‘zlashtirishni aniqlash | Mezonga bog‘langan topshiriq |\n| Aralash dars | Bir nechta didaktik vazifa | Turli bosqichli qisqa dalillar |\n\n**Boshlang‘ich diagnostika** o‘quvchining tayyorligini aniqlaydi. **Formativ tekshiruv** jarayonning keyingi bosqichini o‘zgartirishga dalil beradi. **Yakuniy baholash** belgilangan natijaning erishilgan darajasini qayd etadi.\n\n**Noto‘g‘ri umumlashtirish:** “interfaol metod qo‘llandimi – demak dars turi amaliy” — metodning nomi darsning didaktik vazifasini yakka o‘zi aniqlamaydi.\n\n**Manba izi:** M15 dars turlari va ta’lim metodlari darsi; mustaqil taqqoslash."}]$items$::jsonb)
 as t(module text,slug text,addition text)
 loop
  if (select count(*) from public.lessons l join public.modules m on m.id=l.module_id
      where m.code=r.module and l.slug=r.slug and l.status='published'::public.content_status)<>1
   then raise exception 'missing canonical lesson %.%',r.module,r.slug; end if;
  update public.lessons l set body_mdx=l.body_mdx||E'\n\n'||r.addition,updated_at=now()
  from public.modules m
  where l.module_id=m.id and m.code=r.module and l.slug=r.slug
    and position('[PEDGULI-EXPAND-2026-02]' in coalesce(l.body_mdx,''))=0;
 end loop;
end
$enrich_v2$;
commit;